      const coords3d = polygon.map(coords => coords.map(([lng, lat]) => polar2Cartesian(lat, lng, altFn(lng, lat))));
      // returns { vertices, holes, coordinates }. Each point generates 3 vertice items (x,y,z).
      return flatten(coords3d);
